fn make_api_error(code: u16) -> petstore::api_error::ApiError {
    petstore::api_error::ApiError::new(
        code,
        format!("status {}", code),
        Some(format!("{{\"code\":{}}}", code)),
        Some(HashMap::new()),
    )
}

